/*
 * nano_j2me - nj_font.c
 *
 * The bitmap font registry declared in nj_gfx.h.
 *
 * Design notes
 * ------------
 *  - The glyph tables in nj_font_data.h are generated by tools/gen_fonts.py
 *    and live in .rodata.  nj_font_builtin() hands out pointers to immutable
 *    nj_font descriptors built from them; nothing here is ever written.
 *  - The runtime keeps no mutable global font state.  A caller that wants a
 *    per-instance fallback (the CJK hook, say) owns an nj_fontset: it holds
 *    mutable *copies* of the builtins, one per (size, plain/bold) pair, so
 *    nj_fontset_set_fallback() can install a pointer without touching data
 *    shared with any other nj_vm.
 *  - ITALIC and UNDERLINED have no bitmaps of their own: they reuse the PLAIN
 *    (or BOLD) glyphs and are recorded in nj_font.style for the rasteriser.
 *    That is why s_builtin carries eight entries per size even though there
 *    are only two bitmaps per size.
 *  - The fontset has six slots - three sizes times plain/bold - exactly as
 *    nj_gfx.h documents, so a request for an italic font from a set resolves
 *    to the plain (or bold) instance of that size.  Ask nj_font_builtin()
 *    directly when the style bits themselves matter.
 */

#include "nj2me/nj_gfx.h"

#include "nj_font_data.h"

/* ------------------------------------------------------------------ */
/* Layout constants                                                    */
/* ------------------------------------------------------------------ */

#define NJ_FONT_SIZE_COUNT 3
#define NJ_FONT_STYLE_COUNT 8   /* bold | italic | underlined combinations */
/* NJ_FONT_SLOT_STYLES lives in nj_gfx.h: it is the slot stride, and
 * nj_font_ttf.c indexes the same array. */
#define NJ_FONT_FALLBACK_MAX_DEPTH 8

#define NJ_FONT_STYLE_MASK \
    (NJ_FONT_STYLE_BOLD | NJ_FONT_STYLE_ITALIC | NJ_FONT_STYLE_UNDERLINED)

/*
 * One immutable descriptor.  `bmp` points at one of the generated tables,
 * whose geometry is (last_char - first_char + 1) cells of glyph_h rows of
 * (glyph_w + 7) / 8 bytes - see nj_gfx.h.
 *
 * `wide` expands to the wide-glyph fields in descriptor order - lookup,
 * coverage, ud, advance, fallback and glyph ascent. `coverage`
 * sits between the lookup hook and its `glyph_ud`, and C initialisers cannot
 * step over a field.  The fixed cell only covers ASCII and Latin-1, so this
 * is how a character such as a hanzi is found at all.
 */
#define NJ_FONT_ENTRY(nm, szv, styv, wv, hv, av, dv, lv, bmp, wide) \
    {                                                          \
        (nm), (hv), (av), (dv), (lv), (styv), (szv), 0,        \
        (nj_u2)NJ_FONT_DATA_FIRST, (nj_u2)NJ_FONT_DATA_LAST,   \
        (wv), (hv), (bmp),                                     \
        wide                                                  \
    }

/*
 * ------------------------------------------------------------------
 * Chinese glyphs
 * ------------------------------------------------------------------
 *
 * The fixed cells cover ASCII and Latin-1.  Chinese text is most of what the
 * games in tests/games/ draw, and without a table every hanzi renders as a
 * blank cell - which is indistinguishable from a MIDlet that drew nothing.
 *
 * src/gfx/nj_font_cjk.h (generated by tools/gen_cjk_font.py from Source Han
 * Sans CN) carries the GB2312 charset: 7445 code points, with 12-pixel advances
 * for SMALL/MEDIUM and 16-pixel advances for LARGE. Taller storage cells retain
 * one shared baseline and complete accents/descenders for each face. Each
 * face's index is sorted by code point, so a lookup is a binary search and the
 * glyph starts at
 * index * stride in that face's bitmap.
 *
 * A code point the table does not carry returns NULL, which leaves every
 * other path - the fixed cell, the fallback chain, the placeholder advance -
 * exactly as it was before.
 */
#if NJ_ENABLE_FONT_CJK
#if NJ_ENABLE_FONT_CJK_AA
#include "nj_font_cjk_aa.h"
#else
#include "nj_font_cjk.h"
#define NJ_CJK_COVERAGE 0
#endif

static int cjk_index_of(const nj_u2 *index, nj_u2 count, nj_u2 ch)
{
    nj_u2 lo = 0u;
    nj_u2 hi = count;

    while (lo < hi) {
        nj_u2 mid = (nj_u2)(lo + (nj_u2)((hi - lo) / 2u));
        nj_u2 probe = index[mid];

        if (probe == ch) {
            return (int)mid;
        }
        if (probe < ch) {
            lo = (nj_u2)(mid + 1u);
        } else {
            hi = mid;
        }
    }
    return -1;
}

static const nj_u1 *cjk_lookup_12(void *ud, nj_u2 ch, int *w, int *h)
{
    int i;

    (void)ud;
    i = cjk_index_of(nj_cjk_12_index, (nj_u2)NJ_CJK_12_COUNT, ch);
    if (i < 0) {
        return NULL;
    }
    *w = NJ_CJK_12_W;
    *h = NJ_CJK_12_H;
    return nj_cjk_12_bitmap + (nj_u4)i * (nj_u4)NJ_CJK_12_STRIDE;
}

static const nj_u1 *cjk_lookup_16(void *ud, nj_u2 ch, int *w, int *h)
{
    int i;

    (void)ud;
    i = cjk_index_of(nj_cjk_16_index, (nj_u2)NJ_CJK_16_COUNT, ch);
    if (i < 0) {
        return NULL;
    }
    *w = NJ_CJK_16_W;
    *h = NJ_CJK_16_H;
    return nj_cjk_16_bitmap + (nj_u4)i * (nj_u4)NJ_CJK_16_STRIDE;
}

static int cjk_advance_12(void *ud, nj_u2 ch)
{
    (void)ud;
    return (cjk_index_of(nj_cjk_12_index, (nj_u2)NJ_CJK_12_COUNT, ch) < 0)
               ? 0 : NJ_CJK_12_W;
}

static int cjk_advance_16(void *ud, nj_u2 ch)
{
    (void)ud;
    return (cjk_index_of(nj_cjk_16_index, (nj_u2)NJ_CJK_16_COUNT, ch) < 0)
               ? 0 : NJ_CJK_16_W;
}

/* The provider format does not change the fixed Latin bitmap format. */
#define CJK_WIDE_12 cjk_lookup_12, NJ_CJK_COVERAGE, NULL, cjk_advance_12, NULL, NJ_CJK_12_ASCENT
#define CJK_WIDE_16 cjk_lookup_16, NJ_CJK_COVERAGE, NULL, cjk_advance_16, NULL, NJ_CJK_16_ASCENT
#else
/* No table compiled in: the wide-glyph fields stay empty and a hanzi keeps
 * the placeholder advance it had before this existed. */
#define CJK_WIDE_12 NULL, 0, NULL, NULL, NULL, 0
#define CJK_WIDE_16 NULL, 0, NULL, NULL, NULL, 0
#endif

