/*
 * The immutable builtin table.  Indexed [size][style bits]; the pointer
 * members make this a relocation-bearing const object, which the linker
 * places in .data.rel.ro - read-only once the loader is done, and the
 * no-writable-statics check understands that.
 */
static const nj_font s_builtin[NJ_FONT_SIZE_COUNT][NJ_FONT_STYLE_COUNT] = {
    { NJ_FONT_SMALL_ENTRIES },
    { NJ_FONT_MEDIUM_ENTRIES },
    { NJ_FONT_LARGE_ENTRIES }
};

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* SMALL, MEDIUM, LARGE; anything else means MEDIUM. */
static int size_index(int size)
{
    if (size == NJ_FONT_SIZE_SMALL) {
        return 0;
    }
    if (size == NJ_FONT_SIZE_LARGE) {
        return 2;
    }
    return 1;
}

/* Advance of a wide glyph the fixed cell cannot hold (CJK and friends). */
static int wide_advance(const nj_font *f, nj_u2 ch, int glyph_w)
{
    if (f->glyph_advance != NULL) {
        int adv = f->glyph_advance(f->glyph_ud, ch);
        if (adv > 0) {
            return adv;
        }
    }
    return (glyph_w > 0) ? glyph_w : 1;
}

static int char_width_depth(const nj_font *f, nj_u2 ch, int depth)
{
    int w = 0;
    int h = 0;

    if (f == NULL) {
        return 0;
    }
    if (depth > NJ_FONT_FALLBACK_MAX_DEPTH) {
        /* A cyclic fallback chain: a font that eventually falls back to
         * itself.  Stop recursing and charge one cell so layout stays sane
         * instead of collapsing the character to zero width. */
        return (f->glyph_w > 0) ? f->glyph_w : 1;
    }

    if (ch >= f->first_char && ch <= f->last_char) {
        /* Proportional faces carry their own advance override. */
        if (f->proportional && f->glyph_advance != NULL) {
            return wide_advance(f, ch, f->glyph_w);
        }
        return f->glyph_w;
    }

    /* Outside the cell: a wide-glyph provider may still have it. */
    if (f->glyph_lookup != NULL) {
        const nj_u1 *bits = f->glyph_lookup(f->glyph_ud, ch, &w, &h);
        if (bits != NULL) {
            (void)h;
            return wide_advance(f, ch, w > 0 ? w : f->glyph_w);
        }
    }

    if (f->fallback != NULL) {
        return char_width_depth(f->fallback, ch, depth + 1);
    }

    /*
     * Nothing can draw it.  Report the cell width: an unknown character
     * occupies one cell's worth of space, which keeps layout stable and lets
     * the rasteriser draw a placeholder instead of collapsing the run.
     */
    return f->glyph_w;
}

/* ------------------------------------------------------------------ */
/* Public API                                                          */
/* ------------------------------------------------------------------ */

const nj_font *nj_font_builtin(int size, int style)
{
    int si = size_index(size);
    int st = style & NJ_FONT_STYLE_MASK;
    return &s_builtin[si][st];
}

void nj_fontset_init(nj_fontset *fs)
{
    int size;
    int style;
    int slot;

    if (fs == NULL || fs->initialized) {
        return;   /* idempotent */
    }

    slot = 0;
    for (size = 0; size < NJ_FONT_SIZE_COUNT; size++) {
        for (style = 0; style < NJ_FONT_SLOT_STYLES; style++) {
            if (slot >= NJ_FONTSET_SLOTS) {
                break;
            }
            /* Mutable copy of the immutable builtin: the fallback field of
             * this instance may be written without affecting anyone else. */
            fs->fonts[slot] = s_builtin[size][style];
            slot++;
        }
    }
    fs->count = slot;
    fs->initialized = 1;
}

const nj_font *nj_fontset_get(nj_fontset *fs, int size, int style)
{
    int si;
    int bold;
    int slot;

    if (fs == NULL) {
        return nj_font_builtin(size, style);
    }
    if (!fs->initialized) {
        nj_fontset_init(fs);
    }

    si = size_index(size);
    bold = (style & NJ_FONT_STYLE_BOLD) ? 1 : 0;
    slot = si * NJ_FONT_SLOT_STYLES + bold;
    if (slot < 0 || slot >= fs->count || slot >= NJ_FONTSET_SLOTS) {
        slot = 0;
    }
    return &fs->fonts[slot];
}

void nj_fontset_set_fallback(nj_fontset *fs, const nj_font *fb)
{
    int i;

    if (fs == NULL) {
        return;
    }
    if (!fs->initialized) {
        nj_fontset_init(fs);
    }
    for (i = 0; i < fs->count && i < NJ_FONTSET_SLOTS; i++) {
        fs->fonts[i].fallback = fb;
    }
}

void nj_fontset_set_fallback_slots(nj_fontset *fs, const nj_font *const *fonts,
                                   int count)
{
    int i;

    if (fs == NULL || fonts == NULL) {
        return;
    }
    if (!fs->initialized) {
        nj_fontset_init(fs);
    }
    for (i = 0; i < count && i < fs->count && i < NJ_FONTSET_SLOTS; i++) {
        if (fonts[i] != NULL) {
            fs->fonts[i].fallback = fonts[i];
        }
    }
}

void nj_fontset_set_primary_slots(nj_fontset *fs, const nj_font *const *fonts,
                                  int count)
{
    int i;

    if (fs == NULL || fonts == NULL) {
        return;
    }
    if (!fs->initialized) {
        nj_fontset_init(fs);
    }
    for (i = 0; i < count && i < fs->count && i < NJ_FONTSET_SLOTS; i++) {
        const nj_font *fb;

        if (fonts[i] == NULL) {
            continue;
        }
        /* The chain already behind this slot survives the swap: a port can be
         * the slot for every character and still leave a fallback under it. */
        fb = fs->fonts[i].fallback;
        fs->fonts[i] = *fonts[i];
        fs->fonts[i].fallback = fb;
    }
}

int nj_font_char_width(const nj_font *f, nj_u2 ch)
{
    return char_width_depth(f, ch, 0);
}

int nj_font_string_width(const nj_font *f, const nj_u2 *s, int len)
{
    int i;
    int total = 0;

    if (f == NULL || s == NULL || len == 0) {
        return 0;
    }
    if (len < 0) {
        /* Defensive: -1 means "up to the NUL", like the C string it usually
         * came from.  A UTF-16 string never contains U+0000 in practice. */
        for (i = 0; s[i] != 0u; i++) {
            int w = nj_font_char_width(f, s[i]);
            if (total > 0x3FFFFFFF - w) {
                return 0x3FFFFFFF;   /* saturate instead of wrapping */
            }
            total += w;
        }
        return total;
    }
    for (i = 0; i < len; i++) {
        int w = nj_font_char_width(f, s[i]);
        if (total > 0x3FFFFFFF - w) {
            return 0x3FFFFFFF;
        }
        total += w;
    }
    return total;
}

int nj_font_chars_that_fit(const nj_font *f, const nj_u2 *s, int len, int avail)
{
    int i;
    int used = 0;
    int count = 0;

    if (f == NULL || s == NULL || len <= 0 || avail <= 0) {
        return 0;
    }
    for (i = 0; i < len; i++) {
        int w = nj_font_char_width(f, s[i]);
        if (w < 0) {
            w = 0;
        }
        if (used > avail - w) {   /* used + w > avail, no overflow */
            break;
        }
        used += w;
        count++;
    }
    return count;
}
